namespace properties {

enum class OfSomething : std::uint32_t {
  kInterface = 0,
  kType = 1,
  kRange = 2,
  kVoid = 3
};  // enum class OfSomething

const std::unordered_map<
  std::string,
  OfSomething
> kMapOfSomething = {
  {
    "interface",
    OfSomething::kInterface
  },
  {
    "type",
    OfSomething::kType
  },
  {
    "range",
    OfSomething::kRange
  },
  {
    "void",
    OfSomething::kVoid
  }
};

}  // namespace properties

template <
  typename T,
  typename std::enable_if<
    std::is_base_of<T, types::ISomething>::value
  >::type*
>
std::pair<
  common::optional<std::shared_ptr<T> >,
  common::optional<DeserializationError>
> SomethingFromSequence(
  xml_common::ReaderMergingText& reader
) {
  #ifdef DEBUG
  if (reader.node().kind() == xml_common::NodeKind::Error) {
    throw std::logic_error(
      "Unexpected unhandled XML error in SomethingFromSequence. "
      "SomethingFromSequence expects no reader error at entry."
    );
  }
  #endif

  common::optional<DeserializationError> error;

  error = SkipBof(reader);
  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<T>
    >(
      std::move(*error)
    );
  }

  // region Initialization

  common::optional<std::wstring> the_interface;

  common::optional<std::wstring> the_type;

  common::optional<std::wstring> the_range;

  common::optional<std::wstring> the_void;

  // endregion Initialization

  while (true) {
    error = SkipWhitespace(reader);
    if (error.has_value()) {
      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    if (reader.node().kind() == xml_common::NodeKind::Stop) {
      // NOTE (mristin):
      // We reached a closing element of an instance, so we know that
      // the sequence ended.
      break;
    } else if (reader.node().kind() != xml_common::NodeKind::Start) {
      return NoInstanceAndDeserializationErrorWithCause<
        std::shared_ptr<T>
      >(
        common::Concat(
          L"Expected a start element opening a property "
          L"of ISomething, but got ",
          xml_common::NodeToHumanReadableWstring(reader.node())
        )
      );
    }

    const std::string name(
      static_cast<  // NOLINT(cppcoreguidelines-pro-type-static-cast-downcast)
        const xml_common::StartNode&
      >(reader.node()).name
    );

    // NOTE (mristin):
    // We consume the start element.
    reader.Read();

    if (reader.node().kind() == xml_common::NodeKind::Error) {
      error = DeserializationErrorFromReader(reader);

      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    auto it = properties::kMapOfSomething.find(
      name
    );
    if (it == properties::kMapOfSomething.end()) {
      return NoInstanceAndDeserializationErrorWithCause<
        std::shared_ptr<T>
      >(
        common::Concat(
          L"Expected a start element opening a property "
          L"of ISomething, "
          L"but got a start element "
          L"which does not correspond to any of its properties: <",
          common::Utf8ToWstring(name),
          L">"
        )
      );
    }

    const properties::OfSomething property(
      it->second
    );

    switch (property) {
      case properties::OfSomething::kInterface: {
        std::tie(
          the_interface,
          error
        ) = DeserializeWstring(reader);
        break;
      }
      case properties::OfSomething::kType: {
        std::tie(
          the_type,
          error
        ) = DeserializeWstring(reader);
        break;
      }
      case properties::OfSomething::kRange: {
        std::tie(
          the_range,
          error
        ) = DeserializeWstring(reader);
        break;
      }
      case properties::OfSomething::kVoid: {
        std::tie(
          the_void,
          error
        ) = DeserializeWstring(reader);
        break;
      }
      default:
        throw std::logic_error(
          common::Concat(
            "Unexpected properties literal of "
            "properties::OfSomething: ",
            std::to_string(
              static_cast<uint32_t>(property)
            )
          )
        );
    }

    if (error.has_value()) {
      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    error = SkipWhitespace(reader);
    if (error.has_value()) {
      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    if (!xml_common::IsStopNodeWithName(reader.node(), name)) {
      error = DeserializationError(
        common::Concat(
          L"Expected a stop element </",
          common::Utf8ToWstring(name),
          L"> closing the property "
          L"of ISomething, but got ",
          xml_common::NodeToHumanReadableWstring(reader.node())
        )
      );

      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }

    // NOTE (mristin):
    // We consume the stop element.
    reader.Read();

    if (reader.node().kind() == xml_common::NodeKind::Error) {
      error = DeserializationErrorFromReader(reader);

      PrependElementSegmentToDeserializationError(
        name,
        *error
      );

      return NoInstanceAndDeserializationError<
        std::shared_ptr<T>
      >(
        std::move(*error)
      );
    }
  }

  // region Check required properties

  if (!the_interface.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property interface is missing"
    );
  }

  if (!the_type.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property type is missing"
    );
  }

  if (!the_range.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property range is missing"
    );
  }

  if (!the_void.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<T>
    >(
      L"The required property void is missing"
    );
  }

  // endregion Check required properties

  return std::make_pair(
    common::make_optional<
      std::shared_ptr<T>
    >(
      // NOTE (mristin):
      // We deliberately do not use std::make_shared here to avoid an unnecessary
      // upcast.
      new types::Something(
        std::move(*the_interface),
        std::move(*the_type),
        std::move(*the_range),
        std::move(*the_void)
      )
    ),
    common::nullopt
  );
}

