/**
 * Serialize a property wrapped in its own named XML element.
 */
template <typename T, typename SerializeT>
common::optional<xml_common::SerializationError> SerializePropertyAsElement(
  const std::string& name,
  const T& value,
  xml_common::SelfClosingWriter& writer,
  iteration::Property property,
  const SerializeT& serialize_value
) {
  writer.StartElement(name);
  if (writer.error().has_value()) {
    return writer.move_error();
  }

  common::optional<xml_common::SerializationError> error = serialize_value(value, writer);
  if (error.has_value()) {
    error->path.segments.emplace_front(
      common::make_unique<iteration::PropertySegment>(property)
    );
    return error;
  }

  writer.StopElement(name);
  if (writer.error().has_value()) {
    error = writer.move_error();
    error->path.segments.emplace_front(
      common::make_unique<iteration::PropertySegment>(property)
    );
    return error;
  }

  return common::nullopt;
}

/**
 * \brief Serialize \p that instance as a sequence of XML elements.
 *
 * Each XML element corresponds to a property.
 *
 * \param that instance to be serialized
 * \param writer to write to
 * \return error, if any
 */
common::optional<xml_common::SerializationError> SerializeSomethingAsSequence(
  const types::ISomething& that,
  xml_common::SelfClosingWriter& writer
);

/**
 * Serialize \p that instance to an XML element
 * `<something>`.
 *
 * \param that instance to be serialized
 * \return an error, if any
 */
common::optional<xml_common::SerializationError> SerializeSomethingAsElement(
  const types::ISomething& that,
  xml_common::SelfClosingWriter& writer
);

/** @copybrief SerializeSomethingAsElement(const types::ISomething&, xml_common::SelfClosingWriter& */
common::optional<xml_common::SerializationError> SerializeSomethingPtrAsElement(
  const std::shared_ptr<types::ISomething>& that,
  xml_common::SelfClosingWriter& writer
);

/**
 * \brief Serialize \p that instance as a sequence of XML elements.
 *
 * Each XML element corresponds to a property.
 *
 * \param that instance to be serialized
 * \param writer to write to
 * \return error, if any
 */
common::optional<xml_common::SerializationError> SerializeSomethingAsSequence(
  const types::ISomething& that,
  xml_common::SelfClosingWriter& writer
) {
  common::optional<xml_common::SerializationError> error;

  error = SerializePropertyAsElement(
    "interface",
    that.interface(),
    writer,
    iteration::Property::kInterface,
    SerializeWstring
  );
  if (error.has_value()) {
    return error;
  }

  error = SerializePropertyAsElement(
    "type",
    that.type(),
    writer,
    iteration::Property::kType,
    SerializeWstring
  );
  if (error.has_value()) {
    return error;
  }

  error = SerializePropertyAsElement(
    "range",
    that.range(),
    writer,
    iteration::Property::kRange,
    SerializeWstring
  );
  if (error.has_value()) {
    return error;
  }

  error = SerializePropertyAsElement(
    "void",
    that.voiD(),
    writer,
    iteration::Property::kVoid,
    SerializeWstring
  );
  if (error.has_value()) {
    return error;
  }

  writer.Finish();
  if (writer.error().has_value()) {
    return writer.move_error();
  }

  return common::nullopt;
}

common::optional<xml_common::SerializationError> SerializeSomethingAsElement(
  const types::ISomething& that,
  xml_common::SelfClosingWriter& writer
) {
  common::optional<xml_common::SerializationError> error;

  writer.StartElement(
    "something"
  );
  if (writer.error().has_value()) {
    return writer.move_error();
  }

  error = SerializeSomethingAsSequence(
    that,
    writer
  );
  if (error.has_value()) {
    return error;
  }

  writer.StopElement(
    "something"
  );
  if (writer.error().has_value()) {
    return writer.move_error();
  }

  writer.Finish();
  if (writer.error().has_value()) {
    return writer.move_error();
  }

  return common::nullopt;
}

common::optional<xml_common::SerializationError> SerializeSomethingPtrAsElement(
  const std::shared_ptr<types::ISomething>& that,
  xml_common::SelfClosingWriter& writer
) {
  return SerializeSomethingAsElement(*that, writer);
}

void Serialize(
  const types::IClass& that,
  const WritingOptions& options,
  std::ostream& os
) {
  if (options.write_declaration) {
    os << "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n";
    if (os.bad()) {
      throw SerializationException(
        xml_common::kTheOutputStreamIsInABadState
      );
    }
  }

  xml_common::SelfClosingWriter writer(
    os,
    options.prefix
  );

  common::optional<xml_common::SerializationError> error;

  // NOTE (mristin):
  // Instead of using `Serialize*AsElement`, we write the root XML element
  // in this functions so that we check for the XML namespace only once, namely
  // here. Otherwise, we would have a condition check in <em>every</em> nested
  // `Serialize*AsElement` which could cause a significant efficiency hit.

  // NOTE (mristin):
  // The dynamic casts are necessary due to virtual inheritance. Otherwise,
  // we would have used static casts.

  switch (that.model_type()) {
    case types::ModelType::kSomething:
      if (options.write_namespace) {
        os << (
          "<something "
          "xmlns=\"https://dummy.com\">"
        );
      } else {
        os << "<something>";
      }

      error = xml_common::CheckOstreamState(os);
      if (error.has_value()) {
        break;
      }

      error = SerializeSomethingAsSequence(
        dynamic_cast<
          const types::ISomething&
        >(that),
        writer
      );
      if (error.has_value()) {
        break;
      }

      os << "</something>";

      error = xml_common::CheckOstreamState(os);
      if (error.has_value()) {
        break;
      }

      break;
    default:
      throw std::invalid_argument(
        common::Concat(
          "Invalid model type: ",
          stringification::to_string(that.model_type())
        )
      );
  }

  if (error.has_value()) {
    throw SerializationException(
      std::move(error->cause),
      std::move(error->path)
    );
  }
}

